EL ANILLO REAL DEL REPO (listo para reutilizar tal cual, sin dependencia de hábitos) es Donut en frontend/src/components/common/charts.tsx L179-203 — SVG con strokeDasharray:
export function Donut({ parts, size = 120, thickness = 16, label }: {
  parts: Array<{ value: number; colour: string; name: string }>; size?: number; thickness?: number; label?: string;
}) {
  const total = parts.reduce((a, p) => a + p.value, 0);
  const r = (size - thickness) / 2;
  const c = 2 * Math.PI * r;
  let offset = 0;
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} role="img">
      <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke="var(--nv-elevated)" strokeWidth={thickness} />
      {total > 0 && parts.map((p) => {
        const len = (p.value / total) * c;
        const el = (
          <circle key={p.name} cx={size / 2} cy={size / 2} r={r} fill="none" stroke={p.colour} strokeWidth={thickness}
            strokeDasharray={`${len} ${c - len}`} strokeDashoffset={-offset} transform={`rotate(-90 ${size / 2} ${size / 2})`}>
            <title>{p.name}</title>
          </circle>
        );
        offset += len;
        return el;
      })}
      {label && <text x="50%" y="50%" dominantBaseline="central" textAnchor="middle" fontSize={15} fontWeight={600} fill="var(--nv-text)">{label}</text>}
    </svg>
  );
}
Detalles: arranca a las 12 en punto con rotate(-90 ...); la pista es un <circle> gris var(--nv-elevated); cada parte es otro <circle> con strokeDasharray = longitud / hueco acumulando `offset`; el % central es un <text> opcional. Todo el SVG tiene width/height = size y viewBox cuadrado.

