/** Green → amber → grey, so the ring reads at a glance. */
function ringColour(pct: number): string {
  if (pct >= 80) return "var(--nv-mint)";
  if (pct >= 40) return "var(--nv-accent)";
  if (pct > 0) return "var(--nv-warn)";
  return "var(--nv-line-strong)";
}
