function SideStats() {
  const stats = useHabits((s) => s.stats);
  const rows: Array<[string, number]> = [
    ["Hoy", stats?.day ?? 0], ["Semana", stats?.week ?? 0], ["Mes", stats?.month ?? 0], ["Año", stats?.year ?? 0],
